 async function refreshForRetry(epoch){try{const r=await employeeAuth.request('v1/state');if(epoch===ui.epoch)hydrate(r)}catch{}}
 async function execute(){if(ui.busy||!ui.operation)return false;if(ui.preview&&!ui.uncertain){collectForm();if(JSON.stringify(clean(inputSchema(),ui.draft))!==JSON.stringify(ui.preview.input)){ui.preview=null;ui.key=null}}if(!ui.preview){ui.error='请先检查并预览，核对办理内容后再确认提交。';draw();return false}const epoch=ui.epoch,op=ui.operation,p=clone(ui.preview);if(!ui.key)ui.key=globalThis.crypto?.randomUUID?.()||'web-'+Date.now()+'-'+Math.random().toString(36).slice(2);const key=ui.key;ui.busy=true;ui.error='';draw();try{const result=await employeeAuth.request('v1/operations/'+encodeURIComponent(op.id)+'/execute',{method:'POST',headers:{'Idempotency-Key':key},body:{input:p.input,previewToken:p.token,expectedRevision:p.revision}});if(epoch!==ui.epoch)return false;if(result.state)hydrate({...result,capabilities:ui.capabilities});else {const next=await employeeAuth.request('v1/state');if(epoch!==ui.epoch)return false;hydrate(next)}ui.preview=null;ui.key=null;ui.uncertain=false;ui.operation=null;ui.draft={};const previous=ui.history.pop();restoreView(previous);state.page=previous?.page&&previous.page!=='businessOperation'?previous.page:'home';toast('已保存，平台数据已同步');return true}catch(e){if(epoch!==ui.epoch)return false;ui.error=errorText(e);ui.uncertain=!e.status||e.status>=500;if(ui.uncertain)ui.error+='；请重试确认提交结果，系统会使用同一办理编号避免重复。';if(['REVISION_CONFLICT','STALE_REVISION','PREVIEW_EXPIRED','INVALID_PREVIEW'].includes(e.code)){ui.preview=null;ui.key=null;ui.uncertain=false;await refreshForRetry(epoch)}return false}finally{if(epoch===ui.epoch){ui.busy=false;draw()}}}
 function formHtml(){const schema=inputSchema(),op=ui.operation;return `<section class="card pad business-form ${op.id.startsWith('store.design')?'business-decor-form':''}">${op.id.startsWith('store.design')?`<aside id="business-phone">${phoneHtml(ui.draft.decor)}</aside>`:''}<div class="toolbar"><strong>${html(op.label)}</strong><button type="button" class="btn" onclick="businessAPI.back()" ${ui.busy||ui.uncertain?'disabled':''}>取消</button></div>${['order.confirmReceipt','refund.submit'].includes(op.id)?'<p class="notice">仅在已核实实际线下收付凭据后确认。本操作记录人工到账结果，不会调用支付渠道。</p>':''}<form id="business-form" onsubmit="event.preventDefault();businessAPI.preview()">${op.id==='enrollment.batchCreate'?`<div class="business-tabs"><button type="button" class="${!ui.batchEnrollRows?'active':''}" onclick="businessAPI.batchMode(false)">选择已有学生</button><button type="button" class="${ui.batchEnrollRows?'active':''}" onclick="businessAPI.batchMode(true)">逐人填写报名</button></div>`:''}<div class="business-form-grid">${Object.entries(schema.properties||{}).map(([k,s])=>field(k,s,[k],(schema.required||[]).includes(k))).join('')}</div><p class="business-error" role="alert">${html(ui.error)}</p><div id="business-preview">${ui.preview?`<section class="business-preview"><h3>确认办理内容</h3>${resultHtml(ui.preview.result||ui.preview.input)||'<p>内容已检查，请确认提交。</p>'}</section>`:''}</div><p id="business-preview-hint" class="help">${ui.preview?'请核对办理内容，再确认提交。':'请先检查并预览，核对后确认提交。'}</p><div class="form-actions business-submit-actions"><button type="submit" class="btn" ${ui.busy||ui.uncertain?'disabled':''}>${ui.busy?'正在处理…':'检查并预览'}</button><button type="button" id="business-confirm" class="btn primary" ${!ui.preview||ui.busy?'disabled':''} onclick="businessAPI.execute()">${ui.uncertain?'重试确认提交结果':'确认提交'}</button><button type="button" class="btn" onclick="businessAPI.reloadOptions()" ${ui.busy||ui.uncertain?'disabled':''}>刷新可选数据</button>${op.id.startsWith('store.design')?'<button type="button" class="btn" onclick="businessAPI.restoreDecor()">恢复已保存草稿</button>':''}</div></form></section>`}
 function seedFor(kind,row,op){const seed={};if(idFields[kind]){seed[idFields[kind]]=row.id||row.leadId;const plural=idFields[kind].replace(/Id$/,'Ids');if(op.inputSchema?.properties?.[plural])seed[plural]=[row.id||row.leadId]}if(op.id==='class.schedule')seed.sessions=clone(row.schedule||[]);if(op.id==='order.confirmReceipt')seed.amountCents=Math.max(0,Number(row.amountCents||0)-Number(row.paidCents||0));if(['coupon','group','joint'].includes(kind))seed.type=kind;if(op.id.endsWith('.update')){seed.patch={};const props=op.inputSchema?.properties?.patch?.properties;if(props)for(const k of Object.keys(props))if(row[k]!==undefined)seed.patch[k]=clone(row[k]);else {}else for(const k of Object.keys(op.inputSchema?.properties||{}))if(row[k]!==undefined)seed[k]=clone(row[k]);if(kind==='campuses'&&seed.patch)seed.patch.rooms=clone(row.roomDetails||[]);if(op.inputSchema?.properties?.expectedVersion)seed.expectedVersion=row.version;}return seed}
 function openRow(kind,index,id){const row=dataRows(kind)[index];if(!row)return false;const op=ui.operations.find(x=>x.id===id);return open(id,seedFor(kind,row,op))}
 function rowActions(kind,row,index){const publicLink=kind==='forms'&&row.published===true?`<a class="btn small" href="${html(new URL('public-form.html?id='+encodeURIComponent(row.id),location.href).href)}" target="_blank" rel="noopener">打开公开填写页面</a>`:'';const id=idFields[kind];return publicLink+ operationsFor(kind).filter(op=>id&&(op.inputSchema?.properties?.[id]||op.inputSchema?.properties?.[id.replace(/Id$/,'Ids')])).map(op=>`<button class="btn small" onclick="businessAPI.openRow('${kind}',${index},'${html(op.id)}')">${html(op.label)}</button>`).join('')}
 function rowsHtml(kind){let rows=dataRows(kind),fields=columns[kind]||['name','status'];if(!Array.isArray(rows))return resultHtml(rows);const query=ui.query.trim().toLowerCase();if(state.page==='financeArrears')rows=rows.filter(r=>Number(r.totalCents??r.amountCents??0)>Number(r.paidCents||0));return `<div class="table-wrap"><table class="table business-table"><thead><tr>${fields.map(k=>`<th>${html(summaryLabels[k]||labels[k]||'资料')}</th>`).join('')}</tr></thead><tbody>${rows.map((row,index)=>({row,index:dataRows(kind).findIndex(x=>x.id===row.id)})).filter(({row})=>!query||fields.map(k=>human(k,row[k])).join(' ').toLowerCase().includes(query)).map(({row,index})=>`<tr role="button" tabindex="0" aria-expanded="${ui.expanded===kind+':'+index}" onclick="businessAPI.expand('${kind}',${index})" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();businessAPI.expand('${kind}',${index})}">${fields.map(k=>`<td>${html(human(k,row[k]))}</td>`).join('')}</tr>${ui.expanded===kind+':'+index?`<tr class="business-expanded"><td colspan="${fields.length}"><div class="actions">${rowActions(kind,row,index)||'<span class="muted">当前记录没有可用操作</span>'}</div><details><summary>查看记录</summary>${resultHtml(row)}</details></td></tr>`:''}`).join('')||`<tr><td colspan="${fields.length}" class="empty">暂无记录</td></tr>`}</tbody></table></div>`}

 // The server supplies the readable set. These are workflow views, never authorization checks.
 const leadIdentity=row=>String(row.id||row.leadId||'');
 const leadArchived=row=>row.status==='cold'||row.status==='archived'||row.stage==='已归档';
 function leadConverted(row){if(row.status==='converted'||row.stage==='已报名'||row.conversionSnapshot||row.convertedAt)return true;const students=new Set(dataRows('students').filter(s=>s.originLeadId===leadIdentity(row)).map(s=>s.id));if(row.studentId)students.add(row.studentId);return dataRows('orders').some(o=>(o.originLeadId===leadIdentity(row)||students.has(o.studentId))&&Number(o.paidCents??o.paidMinor??0)>0)}
 function leadRegistrar(row){return row.registrarId||row.registrantId||row.createdBy||''}
 function leadPolicy(){const p=ui.data?.leadPolicy||{};return {reserveDays:Number(p.reserveDays??p.retainDays??14),reclaimDays:Number(p.reclaimDays??p.recycleDays??21),firstFollowHours:Number(p.firstFollowHours??4)}}
 function leadTiming(row,now=Date.now()){
  const assigned=Date.parse(row.assignedAt||row.createdAt),follow=Date.parse(row.assignmentFollowAt||row.firstFollowAt),last=Date.parse(row.lastFollowAt),next=Date.parse(row.nextFollowAt),p=leadPolicy(),end=new Date(now);end.setHours(24,0,0,0);
  const active=!!row.ownerId&&!leadArchived(row)&&!leadConverted(row),valid=Number.isFinite(assigned)&&assigned<=now;
  const first=active&&valid&&(!Number.isFinite(follow)||follow<assigned)&&now>=assigned+p.firstFollowHours*3600000;
  const due=active&&Number.isFinite(next)&&next<end.getTime(),overdue=due&&next<now;
  const effective=Number.isFinite(last)&&last>=assigned?last:assigned,recycle=active&&valid&&now>=assigned+p.reserveDays*86400000&&now>=effective+p.reclaimDays*86400000;
  return {first,due,overdue,recycle,sort:Math.min(first?assigned+p.firstFollowHours*3600000:Infinity,due?next:Infinity)};
 }
 function leadDisplay(row,key){if(key==='name')return row.name||'未命名';if(key==='phone')return row.phone||row.contactPhone||'—';if(key==='ownerId')return row.ownerId?(ui.data?.directory||[]).find(x=>x.id===row.ownerId)?.name||row.owner||'负责人资料暂不可见':'公海未分配';if(key==='registrarId'){const id=leadRegistrar(row);return id===ui.user.id?ui.user.name:(ui.data?.directory||[]).find(x=>x.id===id)?.name||row.registrar||'登记人资料暂不可见'}if(key==='stage')return leadArchived(row)?'已归档':leadConverted(row)?'已报名':row.stage||summaryEnums[row.status]||'新线索';return human(key,row[key])}
 function leadEntries(page=state.page,filtered=true){
  let rows=dataRows('leads').map(row=>({row,timing:leadTiming(row)}));
  if(page==='quickRegister')rows=rows.filter(({row})=>leadRegistrar(row)===ui.user.id);
  if(page==='myLeads'||page==='leadTodo')rows=rows.filter(({row})=>row.ownerId===ui.user.id);
  if(page==='leadTodo')rows=rows.filter(({timing})=>timing.first||timing.due).sort((a,b)=>a.timing.sort-b.timing.sort);
  if(page==='leadDetail')return rows.filter(({row})=>leadIdentity(row)===ui.leadDetailId);
  if(!filtered)return rows;
  if(page==='myLeads')rows=rows.filter(({row})=>ui.leadMineTab==='archived'?leadArchived(row):ui.leadMineTab==='converted'?!leadArchived(row)&&leadConverted(row):!leadArchived(row)&&!leadConverted(row));
  if(page==='leadManage')rows=rows.filter(({row,timing})=>ui.leadManageTab==='all'||(ui.leadManageTab==='archived'?leadArchived(row):!leadArchived(row)&&!leadConverted(row)&&(ui.leadManageTab==='public'?!row.ownerId:ui.leadManageTab==='assigned'?!!row.ownerId:timing.recycle)));
  if(page==='quickRegister'){const f=ui.leadFilters,start=f.from?new Date(f.from+'T00:00:00').getTime():-Infinity,end=f.to?new Date(f.to+'T00:00:00'):null;if(end)end.setDate(end.getDate()+1);rows=rows.filter(({row})=>{const date=Date.parse(row.createdAt);return (!f.from||date>=start)&&(!end||date<end.getTime())&&(!f.stage||leadDisplay(row,'stage')===f.stage)&&(!f.intent||row.intent===f.intent)})}
  const query=ui.query.trim().toLowerCase();return rows.filter(({row})=>!query||['name','phone','guardian','source','ownerId','registrarId','grade','subject'].map(k=>leadDisplay(row,k)).join(' ').toLowerCase().includes(query));
 }
 function leadOperationButton(id,label,seed={},primary=false){const op=ui.operations.find(o=>o.id===id);return permitted(op)?`<button type="button" class="btn ${primary?'primary':''}" onclick="businessAPI.open('${html(id)}',${html(JSON.stringify(seed))})">${html(label||op.label)}</button>`:''}
 function leadWritable(row){const scope=ui.user.scope||{type:'own'};if(scope.type==='all')return true;if(scope.type==='campus')return (scope.campusIds||[]).includes(row.campusId);if(scope.type==='own')return row.ownerId===ui.user.id||row.createdBy===ui.user.id;return false}
 function leadActions(row){if(!leadWritable(row))return '';return operationsFor('leads').filter(op=>op.inputSchema?.properties?.leadId).filter(op=>{if(leadArchived(row))return ['lead.reactivate','lead.update'].includes(op.id);if(op.id==='lead.reactivate')return false;if(op.id==='lead.assign')return !row.ownerId;if(op.id==='lead.transfer')return !!row.ownerId;if(op.id==='lead.release')return !!row.ownerId&&!leadConverted(row);if(op.id==='lead.claim')return !row.ownerId&&!leadConverted(row)&&ui.user.permissions.includes('lead.follow');if(op.id==='lead.archive')return !leadConverted(row);return true}).sort((a,b)=>(a.id==='lead.followup'?-1:0)-(b.id==='lead.followup'?-1:0)).map(op=>`<button type="button" class="btn small ${op.id==='lead.followup'?'primary':''}" onclick="businessAPI.leadAction(${html(JSON.stringify(leadIdentity(row)))},'${html(op.id)}')">${html(op.label)}</button>`).join('')}
 function leadArrow(){return '<svg class="business-lead-arrow" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 19 19 5M7 5h12v12"/></svg>'}
 function leadTable(entries){const page=state.page,fields=page==='quickRegister'?['name','phone','source','createdAt','ownerId','stage','intent']:page==='leadTodo'?['name','phone','source','nextFollowAt','stage']:['name','phone','source','registrarId','ownerId','stage','intent'];return `<div class="table-wrap"><table class="table business-table business-lead-table"><thead><tr>${fields.map(k=>`<th>${html(k==='name'?'学生 / 家长':k==='createdAt'?'登记时间':summaryLabels[k]||labels[k])}</th>`).join('')}${page==='leadTodo'?'<th>待办原因</th>':''}<th><span class="sr-only">操作</span></th></tr></thead><tbody>${entries.map(({row,timing})=>{const id=leadIdentity(row),expanded=ui.expanded==='lead:'+id;return `<tr data-lead-row="${html(id)}" role="button" tabindex="0" aria-expanded="${expanded}" onclick="businessAPI.leadExpand(${html(JSON.stringify(id))})" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();businessAPI.leadExpand(${html(JSON.stringify(id))})}">${fields.map(k=>`<td>${html(leadDisplay(row,k))}${k==='name'&&row.guardian?`<small class="business-lead-guardian">${html(row.guardian)}</small>`:''}</td>`).join('')}${page==='leadTodo'?`<td>${timing.due?`<span class="business-lead-reason ${timing.overdue?'overdue':''}">${timing.overdue?'预约逾期':'今日预约'}</span>`:''}${timing.first?'<span class="business-lead-reason overdue">首次跟进超时</span>':''}</td>`:''}<td>${leadArrow()}</td></tr>${expanded?`<tr class="business-expanded"><td colspan="${fields.length+(page==='leadTodo'?2:1)}"><div class="actions">${leadActions(row)||'<span class="muted">当前记录没有可用操作</span>'}</div><details class="business-lead-details"><summary>查看档案 ${leadArrow()}</summary>${resultHtml(row)}</details></td></tr>`:''}`}).join('')||`<tr><td colspan="${fields.length+2}" class="empty">${page==='leadTodo'?'暂无今日待办':page==='quickRegister'?'暂无本人登记的线索':'暂无符合条件的线索'}</td></tr>`}</tbody></table></div>`}
 function leadRecent(row){const now=new Date(),start=new Date(now);start.setHours(0,0,0,0);start.setDate(start.getDate()-89);const at=Date.parse(row.createdAt);return Number.isFinite(at)&&at>=start.getTime()&&at<=now.getTime()}
 function leadStats(values){return `<section class="card business-stats business-lead-stats">${values.map(([label,count])=>`<div><span>${html(label)}</span><strong>${count}</strong></div>`).join('')}</section>`}
 function leadTabs(items,key){return `<div class="business-tabs" role="tablist">${items.map(([value,label,count])=>`<button type="button" role="tab" aria-selected="${ui[key]===value}" class="${ui[key]===value?'active':''}" onclick="businessAPI.leadTab('${key}','${value}')">${html(label)} <span>${count}</span></button>`).join('')}</div>`}
 function leadFiltersHtml(base){if(!ui.leadFiltersOpen)return '';const f=ui.leadFilters,select=(key,label,values)=>`<label>${label}<select class="select" aria-label="${label}" onchange="businessAPI.leadFilter('${key}',this.value)"><option value="">全部${label}</option>${values.map(v=>`<option ${f[key]===v?'selected':''} value="${html(v)}">${html(v)}</option>`).join('')}</select></label>`;return `<div id="business-lead-filters" class="business-lead-filters"><label>登记开始日期<input class="input" type="date" aria-label="登记开始日期" value="${html(f.from)}" onchange="businessAPI.leadFilter('from',this.value)"></label><label>登记结束日期<input class="input" type="date" aria-label="登记结束日期" value="${html(f.to)}" onchange="businessAPI.leadFilter('to',this.value)"></label>${select('stage','当前阶段',[...new Set(base.map(({row})=>leadDisplay(row,'stage')))])}${select('intent','意向度',[...new Set(['高意向','中意向','低意向',...base.map(({row})=>row.intent).filter(Boolean)])])}<button type="button" class="btn" onclick="businessAPI.leadFilterReset()">清除筛选</button></div>`}
 function leadListHtml(){
  const page=state.page,base=leadEntries(page,false),entries=leadEntries();if(page==='leadDetail'){const row=entries[0]?.row;return `<section class="card pad">${row?`<div class="actions">${leadActions(row)}</div>${resultHtml(row)}`:'<p class="empty">该线索已不在当前授权范围，请刷新后重试。</p>'}</section>`}
  let stats='',tabs='',actions='';
  if(page==='quickRegister'){stats=leadStats([['累计登记',base.length],['有效线索（近90天）',base.filter(({row})=>leadRecent(row)).length],['已转化',base.filter(({row})=>leadConverted(row)).length]]);actions=leadOperationButton('lead.import','批量导入')+leadOperationButton('lead.create','单个登记',{},true)}
  if(page==='leadTodo')stats=leadStats([['待跟进',base.length],['预约逾期',base.filter(({timing})=>timing.overdue).length],['首次跟进超时',base.filter(({timing})=>timing.first).length]]);
  if(page==='myLeads')tabs=leadTabs([['active','可跟进',base.filter(({row})=>!leadArchived(row)&&!leadConverted(row)).length],['converted','已报名',base.filter(({row})=>!leadArchived(row)&&leadConverted(row)).length],['archived','已归档',base.filter(({row})=>leadArchived(row)).length]],'leadMineTab');
  if(page==='leadManage'){tabs=leadTabs([['all','全部',base.length],['public','公海',base.filter(({row})=>!row.ownerId&&!leadArchived(row)&&!leadConverted(row)).length],['assigned','已分配',base.filter(({row})=>!!row.ownerId&&!leadArchived(row)&&!leadConverted(row)).length],['recycle','回收候选',base.filter(({timing})=>timing.recycle).length],['archived','归档',base.filter(({row})=>leadArchived(row)).length]],'leadManageTab');actions=(ui.user.scope?.type==='all'?leadOperationButton('lead.policy.update','线索保留与回收策略设置',leadPolicy()):'')+leadOperationButton('lead.policy.run','试运行策略',{apply:false,policy:leadPolicy()})}
  const applied=Object.values(ui.leadFilters).some(Boolean),filter=page==='quickRegister'?`<button type="button" class="btn business-filter-toggle ${applied?'has-filter':''}" aria-label="${ui.leadFiltersOpen?'收起':'展开'}线索筛选${applied?'，已设置条件':''}" title="筛选" aria-controls="business-lead-filters" aria-expanded="${ui.leadFiltersOpen}" onclick="businessAPI.leadFilterToggle()"><svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M4 5h16l-6 7v6l-4 2v-8Z"/></svg></button>`:'';
  return `${stats}<section class="card pad business-leads">${tabs}<div class="toolbar business-lead-toolbar"><div class="business-lead-search"><input class="input" aria-label="查找线索" placeholder="查找学生、家长或手机号" value="${html(ui.query)}" onchange="businessAPI.search(this.value)">${filter}</div><div class="actions">${actions}<button class="btn" onclick="businessAPI.reload()">刷新</button></div></div>${page==='quickRegister'?leadFiltersHtml(base):''}${leadTable(entries)}<p class="help business-lead-count">共 ${entries.length} 条${page==='leadTodo'?'待跟进线索（同一线索只计一次）':''}</p></section>`;
 }
 function leadDetail(id){if(!dataRows('leads').some(r=>leadIdentity(r)===id))return false;go('leadDetail');ui.leadDetailId=id;draw();return true}
 function leadAction(id,operation){const row=dataRows('leads').find(r=>leadIdentity(r)===id),op=ui.operations.find(o=>o.id===operation);if(!row||!leadWritable(row)||!permitted(op))return false;return open(operation,seedFor('leads',row,op))}

 function setupGuide(){if(!ui.user.roleIds.includes('superadmin')||dataRows('classes').length)return '';const steps=[['创建校区','campus.create'],['新增教师账号','account'],['创建课程','course.create'],['建班与排课','class.create'],['登记学生','student.create'],['办理报名','enrollment.create']];return `<section class="card pad business-setup"><strong>开始使用</strong><p class="muted">按顺序完善机构资料，即可办理教学与招生业务。</p><div class="business-operation-grid">${steps.map(([label,id],i)=>`<button class="btn" onclick="${id==='account'?'employeeAuth.openAccounts()':`businessAPI.open('${id}')`}">${i+1}. ${label}</button>`).join('')}</div></section>`}
 const commonIds=['lead.create','lead.followup','enrollment.create','class.schedule','session.attendance','order.confirmReceipt'];
 function dashboard(){const metrics=ui.data?.metrics,conversion=metrics?`<section class="card pad"><strong>我的销售转化</strong><p>${metrics.lowSample?`样本不足：${Number(metrics.ownLeads)||0} / ${Number(metrics.minimumSample)||10} 条；已转化 ${Number(metrics.converted)||0} 人`:`${(Number(metrics.conversionRate||0)*100).toFixed(1)}% · 已转化 ${Number(metrics.converted)||0} / ${Number(metrics.ownLeads)||0} 人`}</p><span class="help">累计本人归属线索；转化按首笔实收时的归属快照统计。</span></section>`:'';const values=[['线索',dataRows('leads').length],['在读',dataRows('enrollments').filter(x=>x.status!=='withdrawn').length],['待收款',dataRows('orders').filter(r=>Number(r.totalCents||r.amountCents||0)>Number(r.paidCents||0)).length]];return `${setupGuide()}<section class="card business-stats">${values.map(([label,count])=>`<div><span>${label}</span><strong>${count}</strong></div>`).join('')}</section>${conversion}<section class="card pad"><div class="toolbar"><strong>常用操作</strong></div><div class="business-operation-grid">${ui.operations.filter(permitted).sort((a,b)=>commonIds.indexOf(a.id)<0?1:commonIds.indexOf(b.id)<0?-1:commonIds.indexOf(a.id)-commonIds.indexOf(b.id)).slice(0,6).map(op=>`<button class="btn" onclick="businessAPI.open('${html(op.id)}')">${html(op.label)}</button>`).join('')||'<p class="empty">当前账号没有可办理操作</p>'}</div></section>`}
 function scheduleRows(){return dataRows('classes').flatMap(c=>(c.schedule||[]).filter(s=>s.status!=='cancelled').map(s=>({c,s}))).sort((a,b)=>(a.s.date+a.s.time).localeCompare(b.s.date+b.s.time))}
 function scheduleHtml(){
  const rows=scheduleRows(),modes=[['teacher','老师'],['student','学生'],['room','教室'],['campus','校区']],mode=ui.scheduleMode;
  const entities=mode==='teacher'?(ui.data.directory||[]).filter(x=>x.roleIds?.includes('teacher')).map(x=>[x.id,x.name]):mode==='student'?dataRows('students').map(x=>[x.id,x.name]):mode==='campus'?dataRows('campuses').map(x=>[x.id,x.name]):[...new Map(rows.map(({c,s})=>[c.campusId+'|'+(s.room||c.room),[c.campusId+'|'+(s.room||c.room),nameOf('campuses',c.campusId)+' · '+(s.room||c.room)]])).values()];
  const member=(r,id)=>mode==='teacher'?(r.s.teacherId||r.c.teacherId)===id:mode==='student'?(Array.isArray(r.s.studentIds)?r.s.studentIds.includes(id):dataRows('enrollments').some(e=>e.studentId===id&&e.classId===r.c.id&&e.status!=='cancelled'&&e.status!=='withdrawn')):mode==='campus'?(r.s.campusId||r.c.campusId)===id:r.c.campusId+'|'+(r.s.room||r.c.room)===id;
  const filtered=rows.map((r,index)=>({...r,index})).filter(r=>(!ui.scheduleDate||r.s.date===ui.scheduleDate)&&(!ui.scheduleEntity||member(r,ui.scheduleEntity)));
  const controls=`<div class="business-tabs">${modes.map(([id,name])=>`<button class="${id===mode?'active':''}" onclick="businessAPI.scheduleFilter('scheduleMode','${id}')">${name}</button>`).join('')}</div><div class="toolbar"><select class="select" aria-label="课表对象" onchange="businessAPI.scheduleFilter('scheduleEntity',this.value)"><option value="">全部${modes.find(x=>x[0]===mode)[1]}</option>${entities.map(([id,name])=>`<option value="${html(id)}" ${id===ui.scheduleEntity?'selected':''}>${html(name)}</option>`).join('')}</select><input class="input" type="date" aria-label="课表日期" value="${html(ui.scheduleDate)}" onchange="businessAPI.scheduleFilter('scheduleDate',this.value)">${ui.operations.some(x=>x.id==='class.schedule'&&permitted(x))?'<button class="btn primary" onclick="businessAPI.open(\'class.schedule\')">班级排课</button>':''}</div>`;
  let content='';
  if(['room','campus'].includes(mode))content=`<div class="table-wrap"><table class="table business-table"><thead><tr><th>日期</th><th>时间</th><th>班级</th><th>老师</th><th>校区</th><th>教室</th></tr></thead><tbody>${filtered.map(r=>`<tr tabindex="0" role="button" onclick="businessAPI.selectSlot(${r.index})" onkeydown="if(event.key==='Enter')businessAPI.selectSlot(${r.index})"><td>${html(r.s.date)}</td><td>${html(r.s.time)}</td><td>${html(r.c.name)}</td><td>${html(human('teacherId',r.s.teacherId||r.c.teacherId))}</td><td>${html(nameOf('campuses',r.s.campusId||r.c.campusId))}</td><td>${html(r.s.room||r.c.room)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">暂无课次</td></tr>'}</tbody></table></div>`;
  else {
   const lanes=[];for(const [id,name]of entities.filter(([id])=>!ui.scheduleEntity||id===ui.scheduleEntity))for(const date of [...new Set(filtered.filter(r=>member(r,id)).map(r=>r.s.date))])lanes.push({name,date,rows:filtered.filter(r=>r.s.date===date&&member(r,id))});
   const minutes=t=>{const parts=String(t).match(/\d{1,2}:\d{2}/g)||[];return parts.map(x=>{const [h,m]=x.split(':').map(Number);return h*60+m})};
   content=`<div class="caterpillar-legend"><span><i></i>待上课／待确认</span><span><i class="done"></i>已记录</span><span><i class="conflict"></i>时间冲突</span></div><div class="timeline-scroll"><div class="caterpillar-board"><div class="timeline-header"><div>${mode==='teacher'?'老师':'学生'} · 日期</div><div class="timeline-hours">${Array.from({length:13},(_,i)=>`<span style="left:${i/12*100}%">${String(i*2).padStart(2,'0')}:00</span>`).join('')}</div></div>${lanes.map(l=>{const positioned=l.rows.map(r=>({...r,range:minutes(r.s.time)})),ends=[];positioned.forEach(r=>{r.conflict=positioned.some(o=>o!==r&&o.range[0]<r.range[1]&&o.range[1]>r.range[0]);let lane=ends.findIndex(end=>end<=r.range[0]);if(lane<0)lane=ends.length;ends[lane]=r.range[1];r.lane=lane});return `<div class="caterpillar-lane"><div class="caterpillar-label"><strong>${html(l.name)}</strong><span>${html(l.date)}</span></div><div class="caterpillar-track" style="--tick:${100/24}%;height:${Math.max(1,ends.length)*96}px">${positioned.filter(r=>r.range.length===2).map(r=>`<button class="worm-segment ${r.conflict?'is-conflict':dataRows('attendance').some(a=>a.classId===r.c.id&&a.sessionId===r.s.id)?'is-done':''}" style="left:${r.range[0]/1440*100}%;width:${(r.range[1]-r.range[0])/1440*100}%;top:${r.lane*96}px" onclick="businessAPI.selectSlot(${r.index})" title="${html(r.c.name+' '+r.s.time)}"><b>${html(r.s.time)}</b><strong>${html(r.c.name)}</strong><span>${html(lessonLabel(r.c,r.s.lessonId))}</span><small>${html(r.s.room||r.c.room)}</small></button>`).join('')}</div></div>`}).join('')||'<div class="caterpillar-empty">暂无课次，请先建班并排课。</div>'}</div></div>`;
  }
  const selected=ui.selectedSlot===null?null:rows[ui.selectedSlot],actions=selected?`<section class="business-session-actions"><strong>${html(selected.c.name)} · ${html(selected.s.date)} ${html(selected.s.time)}</strong><div class="actions">${ui.operations.filter(op=>op.id.startsWith('session.')&&permitted(op)).map(op=>`<button class="btn small" onclick="businessAPI.sessionAction('${html(op.id)}')">${html(op.label)}</button>`).join('')}</div></section>`:'';
  return `<section class="card pad schedule-panel">${controls}${content}${actions}</section>`;
 }
 function phoneHtml(decor={}){decor=decor||{};const color=/^#[0-9a-f]{6}$/i.test(decor.color)?decor.color:'#315deb';return `<div class="iphone17"><div class="iphone-screen"><div class="iphone-status"><span>9:41</span><i class="dynamic-island"></i><span>▰</span></div><div class="iphone-scroll"><div class="store-brand"><div class="store-monogram" style="background:${color}">思</div><div><strong>${html(decor.title||'课程商城')}</strong><small>${html(decor.subtitle||'')}</small></div></div>${(decor.modules||[]).map(name=>{const block=decor.blocks?.[name]||{},src=/^(https?:\/\/|\/)/.test(block.image||'')?block.image:'';return `<button type="button" class="decor-pick store-block ${ui.decorFocus===name?'chosen':''}" onclick="businessAPI.focusBlock(${html(JSON.stringify(name))})">${src?`<img src="${html(src)}" alt="">`:''}<div class="store-block-copy"><strong>${html(block.title||name)}</strong><small>${html(block.body||'')}</small>${(block.courseIds||[]).map(id=>`<div class="store-course"><b>${html(nameOf('courses',id))}</b></div>`).join('')}${block.cta?`<span class="store-cta" style="background:${color}">${html(block.cta)}</span>`:''}</div></button>`}).join('')}</div><div class="iphone-home"></div></div></div>`}
 function decorHtml(){const decor=ui.data?.decor||{};return `<section class="card pad"><div class="toolbar"><div class="business-tabs"><button class="active">商城装修</button></div><div class="actions">${operationsFor('decor').map(op=>`<button class="btn" onclick="businessAPI.open('${html(op.id)}')">${html(op.label)}</button>`).join('')}</div></div><div class="business-decor-preview">${phoneHtml(decor.draft||decor.published)}<div><strong>${decor.published?'已有发布版本':'尚未发布'}</strong><p class="muted">选择模块即可单独编辑。保存草稿后再发布。</p><div class="business-operation-grid">${(decor.draft?.modules||decor.published?.modules||[]).map(name=>`<button class="btn" onclick="businessAPI.open('store.design.save');businessAPI.focusBlock(${html(JSON.stringify(name))})">${html(name)}</button>`).join('')}</div></div></div></section>`}
 function listHtml(){if(pageInfo()[1]==='leads')return leadListHtml();if(state.page==='schedule')return scheduleHtml();if(state.page==='mallDecor')return decorHtml();const [,kind]=pageInfo();if(kind==='dashboard')return dashboard();const ops=operationsFor(kind),actions=ops.filter(op=>!idFields[kind]||!op.inputSchema?.required?.includes(idFields[kind]));return `<section class="card pad"><div class="toolbar"><input class="input" aria-label="查找记录" placeholder="查找记录" value="${html(ui.query)}" onchange="businessAPI.search(this.value)"><div class="actions">${actions.map(op=>`<button class="btn ${op.id.endsWith('.create')?'primary':''}" onclick="businessAPI.open('${html(op.id)}',${html(JSON.stringify(['coupon','group','joint'].includes(kind)?{type:kind}:{}))})">${html(op.label)}</button>`).join('')}<button class="btn" onclick="businessAPI.reload()">刷新</button></div></div>${rowsHtml(kind)}</section>`}
 function draw(){if(!active()||accountPages.has(state.page))return;const view=document.querySelector('#view');if(!view)return;if(typeof permissionRefreshNavigation==='function')permissionRefreshNavigation();const title=ui.operation?.label||pageInfo()[0];document.querySelector('#crumb').textContent=title;document.querySelectorAll('.menu-item').forEach(e=>e.classList.toggle('active',e.dataset.page===state.page));if(typeof workflowInstallSearch==='function')workflowInstallSearch();const search=document.querySelector('#global-action-search');if(search){search.placeholder='使用搜索功能快速找到操作';search.setAttribute('aria-label','使用搜索功能快速找到操作')}const backButton=document.querySelector('#workspace-back');if(backButton){backButton.disabled=!ui.history.length;backButton.title=backButton.disabled?'已在起始页面':'返回上一页';backButton.setAttribute('aria-label',backButton.title)}view.innerHTML=ui.loading&&!ui.data?'<section class="card pad"><p>正在加载服务器数据…</p></section>':!ui.data?`<section class="card pad"><p class="business-error" role="alert">${html(ui.error||'业务服务尚未连接')}</p><button class="btn primary" onclick="businessAPI.reload()">重新连接</button></section>`:ui.operation?formHtml():`${ui.error?`<p class="business-error" role="alert">${html(ui.error)}</p>`:''}${listHtml()}`;const note=document.getElementById('employee-prototype-notice');if(note)note.textContent=statusText()}
 window.siyueCLI={version:'1.0.0',list:()=>ui.operations.filter(permitted).map(clone),describe(id){const op=ui.operations.find(x=>x.id===id);if(!permitted(op))throw Error('操作未开放或未获授权');return clone(op)},open(id){return open(id)},exportCatalog(){return {version:1,mode:'authenticated',operations:this.list()}}};
 const previousPagePermission=permissionCanVisit;permissionCanVisit=function(page){if(active()&&page==='leadDetail')return dataRows('leads').some(row=>leadIdentity(row)===ui.leadDetailId);return previousPagePermission(page)};
