 const oldSearch=workflowSearchEntries;workflowSearchEntries=function(query){if(!active())return [];const q=String(query||'').trim().toLowerCase();if(!q)return [];const results=ui.operations.filter(op=>permitted(op)&&[op.label,op.id,...(op.aliases||[])].join(' ').toLowerCase().includes(q)).map(op=>({label:op.label,meta:'操作',action:()=>open(op.id)}));for(const [page,[label,kind]]of Object.entries(pages))if(label.includes(q)&&permissionCanVisit(page))results.push({label,meta:'页面',action:()=>go(page)});for(const kind of ['leads','students','courses','classes'])dataRows(kind).forEach((r,index)=>{if([r.name,r.phone,r.title].join(' ').toLowerCase().includes(q))results.push({label:recordLabel(kind,r),meta:({leads:'线索',students:'学生',courses:'课程',classes:'班级'})[kind],action:()=>{if(kind==='leads')return leadDetail(leadIdentity(r));go(Object.keys(pages).find(p=>pages[p][1]===kind));ui.expanded=kind+':'+index;draw()}})});if(/账号|密码|设置/.test(q))results.push({label:'设置与账号',meta:'账号',action:()=>employeeAuth.open()});if(/日志/.test(q)&&(employeeAuth.has('audit.read')||ui.user.roleIds.includes('superadmin')))results.push({label:'操作日志',meta:'平台日志',action:()=>employeeAuth.openAudit()});return results.slice(0,60)};
