 const guardedNames=new Set([...Object.keys(typeof journalLabels==='undefined'?{}:journalLabels),...Object.keys(operationByHandler),'workflowPersist','mallPersist','mfPersist','crmImportCommit','finishFlow','batchCommit','batchExecute','mallSave','mallEnd','commercePublishActivity','workflowPublishOffer','decorRestore','decorRestoreSaved','decorRestorePublished','mfSubmitPreview','platformCampusToggle','consumptionDemoImport']);
