 window.businessAPI={open,openRow,leadDetail,leadAction,leadExpand(id){ui.expanded=ui.expanded==='lead:'+id?null:'lead:'+id;draw()},leadTab(key,value){const options={leadMineTab:['active','converted','archived'],leadManageTab:['all','public','assigned','recycle','archived']};if(options[key]?.includes(value)){ui[key]=value;ui.expanded=null;draw()}},leadFilter(key,value){if(['from','to','stage','intent'].includes(key)){ui.leadFilters[key]=value;ui.expanded=null;draw()}},leadFilterToggle(){ui.leadFiltersOpen=!ui.leadFiltersOpen;draw()},leadFilterReset(){ui.leadFilters={from:'',to:'',stage:'',intent:''};draw()},studentMode(parent,creating){if(ui.busy||ui.uncertain)return;collectForm();const value=get(parent)||{};if(creating){delete value.studentId;value.studentDraft=value.studentDraft||{}}else delete value.studentDraft;if(parent.length)set(parent,value);else ui.draft=value;ui.preview=null;ui.key=null;draw()},batchMode(rows){if(ui.busy||ui.uncertain)return;collectForm();ui.batchEnrollRows=!!rows;if(rows){delete ui.draft.studentIds;ui.draft.rows=ui.draft.rows||[]}else{delete ui.draft.rows;ui.draft.studentIds=ui.draft.studentIds||[]}ui.preview=null;ui.key=null;draw()},scheduleFilter(key,value){if(['scheduleMode','scheduleDate','scheduleEntity'].includes(key)){ui[key]=value;ui.selectedSlot=null;if(key==='scheduleMode')ui.scheduleEntity='';draw()}},selectSlot(index){ui.selectedSlot=index;draw()},sessionAction(id){const row=scheduleRows()[ui.selectedSlot];if(row){const seed={classId:row.c.id,sessionId:row.s.id};if(id==='session.attendance'&&Array.isArray(row.s.studentIds))seed.rows=row.s.studentIds.map(studentId=>{const old=dataRows('attendance').find(a=>a.classId===row.c.id&&a.sessionId===row.s.id&&a.studentId===studentId);return {studentId,status:old?.status||'',...(old?{consume:old.consume}:{})}});open(id,seed)}},focusBlock(name){collectForm();ui.decorFocus=name;if(!ui.operation&&state.page==='mallDecor'){open('store.design.save');return}draw()},restoreDecor(){if(ui.busy||ui.uncertain)return;ui.draft.decor=clone(ui.data?.decor?.draft||ui.data?.decor?.published||{});ui.preview=null;ui.key=null;draw()},back,reload:load,status,statusText,preview,execute,change:changed,input(path,value,type){changed(path,value,type,false)},remove,add(path){add(path,schemaAt(path).items||{type:'string'})},check(path,id,checked){collectForm();const rows=get(path)||[];changed(path,checked?[...new Set([...rows,id])]:rows.filter(x=>x!==id),'array');draw()},expand(kind,index){const key=kind==='leads'?'lead:'+leadIdentity(dataRows('leads')[index]||{}):kind+':'+index;ui.expanded=ui.expanded===key?null:key;draw()},search(value){ui.query=value;draw()},async reloadOptions(){if(ui.busy||ui.uncertain)return;collectForm();const op=ui.operation,draft=clone(ui.draft);const ok=await load();if(ok&&active()){ui.operation=op;ui.draft=draft;ui.preview=null;ui.key=null;state.page='businessOperation';draw()}},snapshot:()=>clone(ui.data),catalog:()=>clone(ui.operations)};
